t.script:
document.addEventListener('DOMContentLoaded', function() {
    const loanAmountInput = document.getElementById('input_loan_amount');
    const loanAmountWordsInput = document.getElementById('input_loan_amount_words');
    const loanRequiredInput = document.querySelector('input[name="loan_required"]');

    function convertNumberToWords(amount) {
        let num = Math.floor(Math.abs(amount));
        if (isNaN(num) || num === 0) return '';

        const units = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 
                       'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
        const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

        function convertGroup(n) {
            let str = '';
            if (n >= 100) {
                str += units[Math.floor(n / 100)] + ' Hundred ';
                n %= 100;
            }
            if (n >= 20) {
                str += tens[Math.floor(n / 10)] + (n % 10 ? ' ' + units[n % 10] : '');
            } else if (n > 0) {
                str += units[n];
            }
            return str.trim();
        }

        let result = '';
        if (num >= 1000000000) {
            result += convertGroup(Math.floor(num / 1000000000)) + ' Billion ';
            num %= 1000000000;
        }
        if (num >= 1000000) {
            result += convertGroup(Math.floor(num / 1000000)) + ' Million ';
            num %= 1000000;
        }
        if (num >= 1000) {
            result += convertGroup(Math.floor(num / 1000)) + ' Thousand ';
            num %= 1000;
        }
        if (num > 0) {
            result += convertGroup(num);
        }

        return result.trim();
    }

    const sanctionedAmountInput = document.querySelector('input[name="sanctioned_amount"]');
    const totalSanctionedLoanInput = document.querySelector('input[name="total_sanctioned_loan"]');
    const installmentsCountInput = document.getElementById('input_installments_count');
    const repayInstallmentsInput = document.querySelector('input[name="repay_installments"]');
    const perInstallmentInput = document.querySelector('input[name="per_installment_amount"]');

    function updateFormAmounts() {
        if (!loanAmountInput) return;
        const val = parseFloat(loanAmountInput.value) || 0;
        if (val > 0) {
            const words = convertNumberToWords(val);
            if (loanAmountWordsInput) loanAmountWordsInput.value = words;
            if (loanRequiredInput) loanRequiredInput.value = val;
            if (sanctionedAmountInput) sanctionedAmountInput.value = val;
            if (totalSanctionedLoanInput) totalSanctionedLoanInput.value = val;

            const instCount = parseInt(installmentsCountInput ? installmentsCountInput.value : 1) || 1;
            if (repayInstallmentsInput) repayInstallmentsInput.value = instCount;
            if (perInstallmentInput) perInstallmentInput.value = (val / instCount).toFixed(2);
        } else {
            if (loanAmountWordsInput) loanAmountWordsInput.value = '';
            if (loanRequiredInput) loanRequiredInput.value = '';
            if (sanctionedAmountInput) sanctionedAmountInput.value = '';
            if (totalSanctionedLoanInput) totalSanctionedLoanInput.value = '';
            if (perInstallmentInput) perInstallmentInput.value = '';
        }
    }

    if (loanAmountInput && !loanAmountInput.readOnly) {
        loanAmountInput.addEventListener('input', updateFormAmounts);
        loanAmountInput.addEventListener('change', updateFormAmounts);
        if (loanAmountInput.value) {
            updateFormAmounts();
        }
    }

    if (installmentsCountInput && !installmentsCountInput.readOnly) {
        installmentsCountInput.addEventListener('input', updateFormAmounts);
        installmentsCountInput.addEventListener('change', updateFormAmounts);
    }

    const attachmentInput = document.getElementById('loan_attachment_file');
    const attachmentLabelText = document.getElementById('attachment_label_text');
    const attachmentFilenameDiv = document.getElementById('attachment_filename');

    if (attachmentInput) {
        attachmentInput.addEventListener('change', function() {
            if (this.files && this.files.length > 0) {
                const fileName = this.files[0].name;
                if (attachmentLabelText) attachmentLabelText.innerText = 'Attached';
                if (attachmentFilenameDiv) {
                    attachmentFilenameDiv.innerText = 'Attached Document: ' + fileName;
                    attachmentFilenameDiv.style.display = 'block';
                }
            }
        });
    }
});
